// Reverse-engineered libstdc++-over-glibc std::stof, dependency-free.
// Harness: reads one candidate string per line from stdin, prints classification.

use std::cmp::Ordering::{self, Equal, Greater, Less};

#[derive(Clone, Debug)]
struct Big {
    d: Vec<u32>,
} // little-endian base 2^32, no trailing zero limbs

impl Big {
    fn zero() -> Big {
        Big { d: Vec::new() }
    }
    fn one() -> Big {
        Big { d: vec![1] }
    }
    fn is_zero(&self) -> bool {
        self.d.is_empty()
    }
    fn trim(&mut self) {
        while let Some(&0) = self.d.last() {
            self.d.pop();
        }
    }
    fn bit_len(&self) -> usize {
        match self.d.last() {
            None => 0,
            Some(&hi) => (self.d.len() - 1) * 32 + (32 - hi.leading_zeros() as usize),
        }
    }
    // self = self*m + a
    fn mul_add_small(&mut self, m: u32, a: u32) {
        let mut carry = a as u64;
        for x in self.d.iter_mut() {
            let v = (*x as u64) * (m as u64) + carry;
            *x = v as u32;
            carry = v >> 32;
        }
        while carry > 0 {
            self.d.push(carry as u32);
            carry >>= 32;
        }
        self.trim();
    }
    fn shl(&self, bits: usize) -> Big {
        if self.is_zero() {
            return Big::zero();
        }
        let words = bits / 32;
        let b = bits % 32;
        let mut out = vec![0u32; words];
        if b == 0 {
            out.extend_from_slice(&self.d);
        } else {
            let mut carry = 0u32;
            for &x in &self.d {
                out.push((x << b) | carry);
                carry = x >> (32 - b);
            }
            if carry > 0 {
                out.push(carry);
            }
        }
        let mut r = Big { d: out };
        r.trim();
        r
    }
    fn cmp(&self, o: &Big) -> Ordering {
        if self.d.len() != o.d.len() {
            return self.d.len().cmp(&o.d.len());
        }
        for i in (0..self.d.len()).rev() {
            if self.d[i] != o.d[i] {
                return self.d[i].cmp(&o.d[i]);
            }
        }
        Equal
    }
    fn sub_assign(&mut self, o: &Big) {
        let mut borrow = 0i64;
        for i in 0..self.d.len() {
            let ov = if i < o.d.len() { o.d[i] as i64 } else { 0 };
            let mut v = self.d[i] as i64 - ov - borrow;
            if v < 0 {
                v += 1i64 << 32;
                borrow = 1;
            } else {
                borrow = 0;
            }
            self.d[i] = v as u32;
        }
        self.trim();
    }
}

fn pow10(k: usize) -> Big {
    let mut r = Big::one();
    let mut n = k;
    while n >= 9 {
        r.mul_add_small(1_000_000_000, 0);
        n -= 9;
    }
    let mut t = 1u32;
    for _ in 0..n {
        t *= 10;
    }
    if t != 1 {
        r.mul_add_small(t, 0);
    }
    r
}

// q = floor(num/den) assuming q < 2^26; returns (q, num - q*den)
fn div_small_q(num: &Big, den: &Big) -> (u32, Big) {
    let mut rem = num.clone();
    let mut q = 0u32;
    for bit in (0..26).rev() {
        let t = den.shl(bit);
        if t.cmp(&rem) != Greater {
            rem.sub_assign(&t);
            q |= 1 << bit;
        }
    }
    (q, rem)
}

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub enum StofErr {
    Invalid,
    OutOfRange,
}

fn ci_match(s: &[u8], i: usize, pat: &[u8]) -> bool {
    if i + pat.len() > s.len() {
        return false;
    }
    for k in 0..pat.len() {
        if s[i + k].to_ascii_lowercase() != pat[k] {
            return false;
        }
    }
    true
}

fn hexval(c: u8) -> Option<u32> {
    match c {
        b'0'..=b'9' => Some((c - b'0') as u32),
        b'a'..=b'f' => Some((c - b'a' + 10) as u32),
        b'A'..=b'F' => Some((c - b'A' + 10) as u32),
        _ => None,
    }
}

const EXP_CLAMP: i64 = 1 << 40;

pub fn stof(s: &[u8]) -> Result<f32, StofErr> {
    let mut i = 0usize;
    while i < s.len() && matches!(s[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let mut neg = false;
    if i < s.len() && (s[i] == b'+' || s[i] == b'-') {
        neg = s[i] == b'-';
        i += 1;
    }
    if ci_match(s, i, b"inf") {
        return Ok(if neg {
            f32::NEG_INFINITY
        } else {
            f32::INFINITY
        });
    }
    if ci_match(s, i, b"nan") {
        return Ok(f32::from_bits(if neg { 0xFFC0_0000 } else { 0x7FC0_0000 }));
    }
    // hex?
    if i + 1 < s.len() && s[i] == b'0' && (s[i + 1] | 0x20) == b'x' {
        let mut j = i + 2;
        let mut dig = Big::zero();
        let mut nd = 0usize; // total hex digits seen
        let mut nsig = 0usize; // significant (after leading zeros)
        let mut frac = 0usize;
        let mut dot = false;
        let mut chunk = 0u32;
        let mut cn = 0u32;
        while j < s.len() {
            let c = s[j];
            if let Some(v) = hexval(c) {
                nd += 1;
                if dot {
                    frac += 1;
                }
                if !(nsig == 0 && v == 0) {
                    nsig += 1;
                    chunk = (chunk << 4) | v;
                    cn += 1;
                    if cn == 7 {
                        dig.mul_add_small(1 << 28, chunk);
                        chunk = 0;
                        cn = 0;
                    }
                }
                j += 1;
            } else if c == b'.' && !dot {
                dot = true;
                j += 1;
            } else {
                break;
            }
        }
        if nd > 0 {
            if cn > 0 {
                dig.mul_add_small(1 << (4 * cn), chunk);
            }
            let mut pexp: i64 = 0;
            if j < s.len() && (s[j] | 0x20) == b'p' {
                let mut k = j + 1;
                let mut es = 1i64;
                if k < s.len() && (s[k] == b'+' || s[k] == b'-') {
                    if s[k] == b'-' {
                        es = -1;
                    }
                    k += 1;
                }
                if k < s.len() && s[k].is_ascii_digit() {
                    let mut e = 0i64;
                    while k < s.len() && s[k].is_ascii_digit() {
                        if e < EXP_CLAMP {
                            e = e * 10 + (s[k] - b'0') as i64;
                        }
                        k += 1;
                    }
                    pexp = es * e;
                    j = k;
                }
            }
            let _ = j;
            if dig.is_zero() {
                return Ok(if neg { -0.0 } else { 0.0 });
            }
            let bexp = pexp - 4 * (frac as i64);
            let bl = dig.bit_len() as i64;
            if bl + bexp > 129 {
                return Err(StofErr::OutOfRange);
            }
            if bl + bexp < -150 {
                return Err(StofErr::OutOfRange);
            }
            let (num, den) = if bexp >= 0 {
                (dig.shl(bexp as usize), Big::one())
            } else {
                (dig, Big::one().shl((-bexp) as usize))
            };
            return finish(num, den, neg);
        }
        // "0x" with no hex digits: strtof consumed only the leading '0'
        return Ok(if neg { -0.0 } else { 0.0 });
    }
    // decimal
    let mut dig = Big::zero();
    let mut nd = 0usize;
    let mut nsig = 0usize;
    let mut frac = 0usize;
    let mut dot = false;
    let mut chunk = 0u32;
    let mut cn = 0u32;
    let mut j = i;
    while j < s.len() {
        let c = s[j];
        if c.is_ascii_digit() {
            nd += 1;
            if dot {
                frac += 1;
            }
            let v = (c - b'0') as u32;
            if !(nsig == 0 && v == 0) {
                nsig += 1;
                chunk = chunk * 10 + v;
                cn += 1;
                if cn == 9 {
                    dig.mul_add_small(1_000_000_000, chunk);
                    chunk = 0;
                    cn = 0;
                }
            }
            j += 1;
        } else if c == b'.' && !dot {
            dot = true;
            j += 1;
        } else {
            break;
        }
    }
    if nd == 0 {
        return Err(StofErr::Invalid);
    }
    if cn > 0 {
        let mut p = 1u32;
        for _ in 0..cn {
            p *= 10;
        }
        dig.mul_add_small(p, chunk);
    }
    let mut dexp: i64 = 0;
    if j < s.len() && (s[j] | 0x20) == b'e' {
        let mut k = j + 1;
        let mut es = 1i64;
        if k < s.len() && (s[k] == b'+' || s[k] == b'-') {
            if s[k] == b'-' {
                es = -1;
            }
            k += 1;
        }
        if k < s.len() && s[k].is_ascii_digit() {
            let mut e = 0i64;
            while k < s.len() && s[k].is_ascii_digit() {
                if e < EXP_CLAMP {
                    e = e * 10 + (s[k] - b'0') as i64;
                }
                k += 1;
            }
            dexp = es * e;
            j = k;
        }
    }
    let _ = j;
    if dig.is_zero() {
        return Ok(if neg { -0.0 } else { 0.0 });
    }
    let dexp = dexp - frac as i64;
    let nsig = nsig as i64;
    if nsig + dexp > 40 {
        return Err(StofErr::OutOfRange);
    }
    if nsig + dexp < -46 {
        return Err(StofErr::OutOfRange);
    }
    let (num, den) = if dexp >= 0 {
        let mut n = dig;
        let p = pow10(dexp as usize);
        // multiply n by p: p is a power of ten built limb-wise; do repeated small muls instead
        let _ = p;
        let mut left = dexp as usize;
        while left >= 9 {
            n.mul_add_small(1_000_000_000, 0);
            left -= 9;
        }
        let mut t = 1u32;
        for _ in 0..left {
            t *= 10;
        }
        if t != 1 {
            n.mul_add_small(t, 0);
        }
        (n, Big::one())
    } else {
        (dig, pow10((-dexp) as usize))
    };
    finish(num, den, neg)
}

fn finish(num: Big, den: Big, neg: bool) -> Result<f32, StofErr> {
    // value = num/den, num != 0
    let a = num.bit_len() as i64;
    let b = den.bit_len() as i64;
    let mut e = a - b;
    let ge = if e >= 0 {
        num.cmp(&den.shl(e as usize)) != Less
    } else {
        num.shl((-e) as usize).cmp(&den) != Less
    };
    if !ge {
        e -= 1;
    }
    if e > 128 {
        return Err(StofErr::OutOfRange);
    }
    if e < -150 {
        return Err(StofErr::OutOfRange);
    }
    let t = 23 - e;
    let (n2, d2) = if t >= 0 {
        (num.shl(t as usize), den)
    } else {
        (num, den.shl((-t) as usize))
    };
    let (m, rem) = div_small_q(&n2, &d2);
    debug_assert!((1 << 23) <= m && m < (1 << 24), "m={:x} e={}", m, e);
    let f_zero = rem.is_zero();
    let cmp_half = rem.shl(1).cmp(&d2); // f vs 1/2

    if e < -126 {
        let shift = (-126 - e) as u32; // 1..=24
        let round_away_pre = cmp_half == Greater || (cmp_half == Equal && (m & 1) == 1);
        let is_tiny = !(shift == 1 && m == 0xFF_FFFF && round_away_pre);
        let mb_orig = !(f_zero || cmp_half == Equal);
        let erange = is_tiny && ((m & ((1u32 << shift) - 1)) != 0 || mb_orig);
        let q = m >> shift;
        let dropped = m & ((1u32 << shift) - 1);
        let half = 1u32 << (shift - 1);
        let up = dropped > half || (dropped == half && (!f_zero || (q & 1) == 1));
        let q2 = q + if up { 1 } else { 0 };
        if erange {
            return Err(StofErr::OutOfRange);
        }
        let bits = q2 | if neg { 0x8000_0000 } else { 0 };
        return Ok(f32::from_bits(bits));
    }
    let up = cmp_half == Greater || (cmp_half == Equal && (m & 1) == 1);
    let mut mm = m + if up { 1 } else { 0 };
    let mut ee = e;
    if mm == 0x100_0000 {
        mm = 0x80_0000;
        ee += 1;
    }
    if ee > 127 {
        return Err(StofErr::OutOfRange);
    }
    let bits = (((ee + 127) as u32) << 23) | (mm & 0x7F_FFFF) | if neg { 0x8000_0000 } else { 0 };
    Ok(f32::from_bits(bits))
}

fn main() {
    use std::io::{BufRead, Write};
    let stdin = std::io::stdin();
    let out = std::io::stdout();
    let mut w = std::io::BufWriter::new(out.lock());
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        match stof(line.as_bytes()) {
            Ok(v) => writeln!(w, "OK {:08x}", v.to_bits()).unwrap(),
            Err(StofErr::Invalid) => writeln!(w, "INVALID").unwrap(),
            Err(StofErr::OutOfRange) => writeln!(w, "RANGE").unwrap(),
        }
    }
}

