// ---- cross-check support: exact decimal rendering + oracle ----
impl Big {
    fn div_small(&mut self, d: u32) -> u32 {
        let mut rem = 0u64;
        for i in (0..self.d.len()).rev() {
            let cur = (rem << 32) | self.d[i] as u64;
            self.d[i] = (cur / d as u64) as u32;
            rem = cur % d as u64;
        }
        self.trim();
        rem as u32
    }
    fn to_dec(&self) -> String {
        if self.is_zero() { return "0".to_string(); }
        let mut t = self.clone(); let mut parts: Vec<u32> = Vec::new();
        while !t.is_zero() { parts.push(t.div_small(1_000_000_000)); }
        let mut s = format!("{}", parts.pop().unwrap());
        while let Some(p) = parts.pop() { s.push_str(&format!("{:09}", p)); }
        s
    }
}
// value = dig * base^exp  where base is 10 (kind=10) or 2 (kind=2); returns exact decimal string
fn exact_dec(dig: &Big, exp: i64, kind: u32, neg: bool) -> String {
    let mut n = dig.clone();
    let mut shift = 0usize; // digits after the point
    if kind == 10 {
        if exp >= 0 { let mut k = exp; while k >= 9 { n.mul_add_small(1_000_000_000,0); k-=9; } let mut t=1u32; for _ in 0..k {t*=10;} if t!=1 {n.mul_add_small(t,0);} }
        else { shift = (-exp) as usize; }
    } else {
        if exp >= 0 { n = n.shl(exp as usize); }
        else { let p = (-exp) as usize; shift = p; let mut k = p; while k >= 12 { n.mul_add_small(244140625,0); k-=12; } for _ in 0..k { n.mul_add_small(5,0); } }
    }
    let s = n.to_dec();
    let mut body = if shift == 0 { s }
      else if s.len() > shift { format!("{}.{}", &s[..s.len()-shift], &s[s.len()-shift..]) }
      else { format!("0.{}{}", "0".repeat(shift - s.len()), s) };
    if neg { body.insert(0, '-'); }
    body
}
