// Instrumented reparse: returns (dig, exp, kind, neg) for numeric forms, or None for specials.
fn reparse(s: &[u8]) -> Option<(Big, i64, u32, bool)> {
    let mut i = 0usize;
    while i < s.len() && matches!(s[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') { i += 1; }
    let mut neg = false;
    if i < s.len() && (s[i] == b'+' || s[i] == b'-') { neg = s[i] == b'-'; i += 1; }
    if ci_match(s, i, b"inf") || ci_match(s, i, b"nan") { return None; }
    if i + 1 < s.len() && s[i] == b'0' && (s[i+1] | 0x20) == b'x' {
        let mut j = i + 2; let mut dig = Big::zero(); let mut nd=0usize; let mut frac=0usize; let mut dot=false;
        while j < s.len() {
            let c = s[j];
            if let Some(v) = hexval(c) { nd+=1; if dot {frac+=1;} dig.mul_add_small(16, v); j+=1; }
            else if c == b'.' && !dot { dot=true; j+=1; } else { break; }
        }
        if nd == 0 { return None; }
        let mut pexp = 0i64;
        if j < s.len() && (s[j] | 0x20) == b'p' {
            let mut k=j+1; let mut es=1i64;
            if k<s.len() && (s[k]==b'+'||s[k]==b'-') { if s[k]==b'-' {es=-1;} k+=1; }
            if k<s.len() && s[k].is_ascii_digit() { let mut e=0i64; while k<s.len() && s[k].is_ascii_digit() { if e<EXP_CLAMP { e=e*10+(s[k]-b'0') as i64; } k+=1; } pexp=es*e; }
        }
        return Some((dig, pexp - 4*frac as i64, 2, neg));
    }
    let mut j=i; let mut dig=Big::zero(); let mut nd=0usize; let mut frac=0usize; let mut dot=false;
    while j < s.len() {
        let c=s[j];
        if c.is_ascii_digit() { nd+=1; if dot {frac+=1;} dig.mul_add_small(10,(c-b'0') as u32); j+=1; }
        else if c==b'.' && !dot { dot=true; j+=1; } else { break; }
    }
    if nd == 0 { return None; }
    let mut dexp=0i64;
    if j<s.len() && (s[j]|0x20)==b'e' {
        let mut k=j+1; let mut es=1i64;
        if k<s.len() && (s[k]==b'+'||s[k]==b'-') { if s[k]==b'-' {es=-1;} k+=1; }
        if k<s.len() && s[k].is_ascii_digit() { let mut e=0i64; while k<s.len() && s[k].is_ascii_digit() { if e<EXP_CLAMP { e=e*10+(s[k]-b'0') as i64; } k+=1; } dexp=es*e; }
    }
    Some((dig, dexp - frac as i64, 10, neg))
}

fn cross_main() {
    use std::io::{BufRead, Write};
    let stdin = std::io::stdin();
    let out = std::io::stdout();
    let mut w = std::io::BufWriter::new(out.lock());
    let mut checked = 0u64; let mut skipped = 0u64;
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let mine = stof(line.as_bytes());
        if let Ok(v) = mine {
            if let Some((dig, exp, kind, neg)) = reparse(line.as_bytes()) {
                // skip absurd exponents where the exact decimal would be gigantic
                if exp.abs() > 4000 { skipped += 1; continue; }
                let ds = exact_dec(&dig, exp, kind, neg);
                let oracle: f32 = ds.parse().unwrap();
                if oracle.to_bits() != v.to_bits() {
                    writeln!(w, "MISMATCH input=[{}] exact=[{}] mine={:08x} oracle={:08x}", line, ds, v.to_bits(), oracle.to_bits()).unwrap();
                }
                checked += 1;
            } else { skipped += 1; }
        }
    }
    writeln!(w, "checked={} skipped={}", checked, skipped).unwrap();
